<script setup>
import {computed} from 'vue';import {simulateEvidence,evidenceViews} from '../sim/models/evidence.mjs';import {useLabSession} from '../sim/session.mjs';
const s=useLabSession('evidence');const r=computed(()=>simulateEvidence({s.failure:s.s.failure,s.view:s.s.view}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>注入情境</span><div class="sim-segment"><button :aria-pressed="s.failure==='worker-crash'" @click="s.failure='worker-crash'">Worker crash</button><button :aria-pressed="s.failure==='none'" @click="s.failure='none'">正常完成</button></div></div><div class="sim-control-wide"><span>你現在拿哪一種證據？</span><div class="sim-segment"><button v-for="(v,id) in evidenceViews" :key="id" :aria-pressed="s.view===id" @click="s.view=id">{{v.label}}</button></div></div></div><div class="evidence-layout"><div class="sim-system evidence-system"><div class="sim-node">API<span>JOB-42</span></div><div class="sim-arrow">→</div><div class="sim-node">Queue<span>handoff</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':s.failure==='worker-crash'}]">Worker<span>{{s.failure==='worker-crash'?'crashed':'completed'}}</span></div><div class="sim-arrow">→</div><div :class="['sim-node',{'is-warning':s.failure==='worker-crash'}]">Artifact<span>{{s.failure==='worker-crash'?'unknown':'present'}}</span></div></div><div class="evidence-panel"><p class="v2-result-label">{{evidenceViews[s.view].question}}</p><ul><li v-for="item in r.items" :key="item">{{item}}</li></ul></div></div><div class="sim-consequence"><strong>這份證據能支持到哪裡？</strong><p>{{r.conclusion}}</p></div></section></template>